operation.add:
public function setRobots($robots) {
	$this->robots = $robots;
}

public function getRobots() {
	return $this->robots;
}

if (isset($this->request->post['noindex'])) {
	$data['noindex'] = 1;
} elseif (!empty($information_info) && !empty($information_info['noindex'])) {
	$data['noindex'] = 1;
} else {
	$data['noindex'] = 0;
}

if (isset($this->request->post['show_shipping_rates'])) {
	$data['show_shipping_rates'] = 1;
} elseif (!empty($information_info) && !empty($information_info['show_shipping_rates'])) {
	$data['show_shipping_rates'] = 1;
} else {
	$data['show_shipping_rates'] = 0;
}

if (isset($this->request->post['show_in_footer_info_links'])) {
	$data['show_in_footer_info_links'] = 1;
} elseif (!empty($information_info) && !empty($information_info['show_in_footer_info_links'])) {
	$data['show_in_footer_info_links'] = 1;
} else {
	$data['show_in_footer_info_links'] = 0;
}

$data['shipping_rates_html'] = '';

if (!empty($information_info['show_shipping_rates'])) {
	$this->load->model('extension/module/cyberpunks_shop_information_additional_fields');
	$shipping_rates = $this->model_extension_module_cyberpunks_shop_information_additional_fields->getShippingRatesOverview();

	if ($shipping_rates) {
		$this->load->language('extension/module/cyberpunks_shop_information_additional_fields');

		$data['shipping_rates_html'] = $this->load->view('information/shipping_rates_table', array(
			'shipping_rates'              => $shipping_rates,
			'text_shipping_rates_heading' => $this->language->get('text_shipping_rates_heading'),
			'column_zone'                 => $this->language->get('column_zone'),
			'column_countries'            => $this->language->get('column_countries'),
			'column_service'              => $this->language->get('column_service'),
			'column_delivery'             => $this->language->get('column_delivery'),
			'column_price'                => $this->language->get('column_price')
		));
	}
}

// Shortcode [contact_form] in Description → themed form (posts to information/contact).
if (strpos($data['description'], '[contact_form]') !== false) {
	$this->load->language('information/contact');

	$contact_form_html = $this->load->view('information/partials/contact_form', array(
		'contact_form_action' => $this->url->link('information/contact', '', true),
		'entry_email'         => $this->language->get('entry_email')
	));

	$data['description'] = str_replace('[contact_form]', $contact_form_html, $data['description']);
}

$cyberpunks_contact_ajax = !empty($this->request->server['HTTP_X_REQUESTED_WITH']) && strtolower($this->request->server['HTTP_X_REQUESTED_WITH']) === 'xmlhttprequest';

// Honeypot from Information [contact_form]
if ($this->request->server['REQUEST_METHOD'] == 'POST' && !empty($this->request->post['website'])) {
	if ($cyberpunks_contact_ajax) {
		$this->response->addHeader('Content-Type: application/json');
		$this->response->setOutput(json_encode(array('success' => $this->language->get('text_message_plain'))));
		return;
	}
	$this->response->redirect($this->url->link('information/contact/success'));
}

if (($this->request->server['REQUEST_METHOD'] == 'POST') && $this->validate()) {
	$mail = new Mail($this->config->get('config_mail_engine'));
	$mail->parameter = $this->config->get('config_mail_parameter');
	$mail->smtp_hostname = $this->config->get('config_mail_smtp_hostname');
	$mail->smtp_username = $this->config->get('config_mail_smtp_username');
	$mail->smtp_password = html_entity_decode($this->config->get('config_mail_smtp_password'), ENT_QUOTES, 'UTF-8');
	$mail->smtp_port = $this->config->get('config_mail_smtp_port');
	$mail->smtp_timeout = $this->config->get('config_mail_smtp_timeout');

	$mail->setTo($this->config->get('config_email'));
	$mail->setFrom($this->config->get('config_email'));
	$mail->setReplyTo($this->request->post['email']);
	$mail->setSender(html_entity_decode($this->request->post['name'], ENT_QUOTES, 'UTF-8'));
	$mail->setSubject(html_entity_decode(sprintf($this->language->get('email_subject'), $this->request->post['email']), ENT_QUOTES, 'UTF-8'));
	$mail->setText($this->request->post['enquiry']);
	$mail->send();

	$mail_user = new Mail($this->config->get('config_mail_engine'));
	$mail_user->parameter = $this->config->get('config_mail_parameter');
	$mail_user->smtp_hostname = $this->config->get('config_mail_smtp_hostname');
	$mail_user->smtp_username = $this->config->get('config_mail_smtp_username');
	$mail_user->smtp_password = html_entity_decode($this->config->get('config_mail_smtp_password'), ENT_QUOTES, 'UTF-8');
	$mail_user->smtp_port = $this->config->get('config_mail_smtp_port');
	$mail_user->smtp_timeout = $this->config->get('config_mail_smtp_timeout');
	$mail_user->setTo($this->request->post['email']);
	$mail_user->setFrom($this->config->get('config_email'));
	$mail_user->setSender(html_entity_decode($this->config->get('config_name'), ENT_QUOTES, 'UTF-8'));
	$mail_user->setSubject(html_entity_decode(sprintf($this->language->get('email_subject_auto'), $this->config->get('config_name')), ENT_QUOTES, 'UTF-8'));
	$mail_user->setText($this->language->get('email_text_auto'));
	$mail_user->send();

	if ($cyberpunks_contact_ajax) {
		$this->response->addHeader('Content-Type: application/json');
		$this->response->setOutput(json_encode(array('success' => $this->language->get('text_message_plain'))));
		return;
	}

	$this->response->redirect($this->url->link('information/contact/success'));
}

if ($cyberpunks_contact_ajax && ($this->request->server['REQUEST_METHOD'] == 'POST')) {
	$error = '';
	if (!empty($this->error['email'])) {
		$error = $this->error['email'];
	} elseif (!empty($this->error['enquiry'])) {
		$error = $this->error['enquiry'];
	} elseif (!empty($this->error['name'])) {
		$error = $this->error['name'];
	} elseif (!empty($this->error['captcha'])) {
		$error = $this->error['captcha'];
	} else {
		$error = 'Could not send your message.';
	}
	$this->response->addHeader('Content-Type: application/json');
	$this->response->setOutput(json_encode(array('error' => $error)));
	return;
}

$_['email_subject']  = 'Support request — %s';
$_['email_subject_auto'] = 'We received your message — %s';
$_['email_text_auto']    = "Thanks for contacting Cyberpunks Shop support.\n\nWe have received your message and will reply as soon as we can. You do not need to respond to this email.\n";
$_['text_message_plain'] = 'Thanks — your message has been sent. We will get back to you soon.';

{% if robots %}
<meta name="robots" content="{{ robots }}" />
{% endif %}
